import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.Dh3ZG9qC.js";const u=JSON.parse('{"title":"工作台与状态条","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workbench.md","filePath":"guide/workbench.md","lastUpdated":null}'),d={name:"guide/workbench.md"};function n(i,t,l,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="工作台与状态条" tabindex="-1">工作台与状态条 <a class="header-anchor" href="#工作台与状态条" aria-label="Permalink to &quot;工作台与状态条&quot;">​</a></h1><p>工作台是默认首页：左侧查看设备画面，右侧使用插件提供的编辑与分析面板。</p><h2 id="顶部工具栏" tabindex="-1">顶部工具栏 <a class="header-anchor" href="#顶部工具栏" aria-label="Permalink to &quot;顶部工具栏&quot;">​</a></h2><ul><li><strong>设备</strong>：选择设备、连接、刷新扫描，以及新增、设置、安装应用和删除等管理操作。</li><li><strong>应用</strong>：读取并选择 Android 应用，启动或停止应用。</li><li><strong>操控</strong>：根据当前功能切换输入方式、映射或其他设备操作。</li><li><strong>配置</strong>：选择脚本、模板和项目所使用的数据上下文。</li></ul><p>设备回答“在哪运行”，应用回答“操作哪个应用”，配置回答“使用哪组资源”。切换配置不会自动修改设备上的 Android 应用。</p><h2 id="调整操作空间" tabindex="-1">调整操作空间 <a class="header-anchor" href="#调整操作空间" aria-label="Permalink to &quot;调整操作空间&quot;">​</a></h2><p>拖动投屏与右侧面板之间的分隔条，调整两侧宽度。舞台会保持画面比例，并在可用空间中居中；拖动受最小操作空间与画面比例约束。</p><p>右侧功能页签可以拖动调整顺序。自动化、函数、模板、映射、视频等页签来自插件，实际可见项取决于启用状态与当前应用。</p><h2 id="轻状态条" tabindex="-1">轻状态条 <a class="header-anchor" href="#轻状态条" aria-label="Permalink to &quot;轻状态条&quot;">​</a></h2><p>状态条展示当前操作产生的反馈，而不是重复放置工具栏按钮。</p><table tabindex="0"><thead><tr><th>区域</th><th>典型内容</th><th>便捷操作</th></tr></thead><tbody><tr><td>左侧</td><td>投屏分辨率、帧率、延迟、传输速率、键盘控制与点击坐标</td><td>复制坐标、查看详情</td></tr><tr><td>右侧</td><td>插件保存状态、运行步骤、匹配与执行结果</td><td>查看详情、定位报错</td></tr></tbody></table><p>中间分隔位置可拖动，默认两侧各占一半。空间不足时条目会被裁切，悬停可查看完整信息。</p><p>点击画面后，可复制分辨率坐标或相对坐标。编写跨分辨率的触控步骤时，通常使用 0～1 范围内的相对坐标，例如 <code>[0.5, 0.8]</code>。</p><h2 id="运行与编辑" tabindex="-1">运行与编辑 <a class="header-anchor" href="#运行与编辑" aria-label="Permalink to &quot;运行与编辑&quot;">​</a></h2><p>保存状态与运行状态分别反映当前资源是否已落盘、设备是否在执行。运行中的资源不应同时改写执行流程；先停止运行，再继续编辑。错误定位基于此次运行的资源版本，若源文件已经改变，先核对版本和步骤内容。</p>',15)])])}const _=a(d,[["render",n]]);export{u as __pageData,_ as default};
